  # A day on the Gregorian calendar.
  class GregorianDate
    # The year, for example 2024.
    attr_reader :year

    # The month, 1 to 12.
    attr_reader :month

    # The day of the month, from 1.
    attr_reader :day

    def initialize(year:, month:, day:)
      @year = year
      @month = month
      @day = day
    end

    # Structural equality over every field.
    def ==(other)
      other.is_a?(GregorianDate) &&
        year == other.year &&
        month == other.month &&
        day == other.day
    end
  end

  # Facts about a Hebrew year.
  class YearInfo
    # The year, for example 5785.
    attr_reader :year

    # Whether it has 13 months.
    attr_reader :is_leap

    # The number of days, 353 to 385.
    attr_reader :days

    # Whether Cheshvan and Kislev are long or short.
    attr_reader :length

    # Whether Cheshvan has 30 days.
    attr_reader :is_cheshvan_long

    # Whether Kislev has 29 days.
    attr_reader :is_kislev_short

    # The months in order, from Tishrei.
    attr_reader :months

    def initialize(year:, is_leap:, days:, length:, is_cheshvan_long:, is_kislev_short:, months:)
      @year = year
      @is_leap = is_leap
      @days = days
      @length = length
      @is_cheshvan_long = is_cheshvan_long
      @is_kislev_short = is_kislev_short
      @months = months
    end

    # Structural equality over every field.
    def ==(other)
      other.is_a?(YearInfo) &&
        year == other.year &&
        is_leap == other.is_leap &&
        days == other.days &&
        length == other.length &&
        is_cheshvan_long == other.is_cheshvan_long &&
        is_kislev_short == other.is_kislev_short &&
        months == other.months
    end
  end

  # @api private
  # Packs a GregorianDate into the value-buffer wire format.
  def self._wv_write_gregorian_date(w, v)
    w.write_i32(v.year)
    w.write_i32(v.month)
    w.write_i32(v.day)
  end

  # @api private
  # Unpacks a GregorianDate from the value-buffer wire format.
  def self._wv_read_gregorian_date(r)
    GregorianDate.new(year: r.read_i32, month: r.read_i32, day: r.read_i32)
  end

  # @api private
  # Packs a YearInfo into the value-buffer wire format.
  def self._wv_write_year_info(w, v)
    w.write_i32(v.year)
    w.write_bool(v.is_leap)
    w.write_i32(v.days)
    w.write_i32(v.length)
    w.write_bool(v.is_cheshvan_long)
    w.write_bool(v.is_kislev_short)
    _wv_write_list_hebrew_month(w, v.months)
  end

  # @api private
  # Unpacks a YearInfo from the value-buffer wire format.
  def self._wv_read_year_info(r)
    YearInfo.new(
      year: r.read_i32,
