  # A day on the Hebrew calendar: the civil day it mostly overlaps, since a Hebrew day
  # begins at nightfall. Years 1 to 9999.
  class HebrewDate < WvObject
    WV_PTR = HebrewDatePtr

    # @api private
    def self._wv_clone(ptr)
      Kosherz.kosherz_calendar_HebrewDate_clone(ptr)
    end

    # The date `day` `month` `year`, for example 15 Nisan 5785.
    #
    # # Errors
    #
    # `CalendarError::InvalidDate` when there is no such day: day 0, day 30 of a 29-day
    # month, Adar I in a common year, or a year outside the supported range.
    def initialize(year, month, day)
      err = ErrorStruct.new
      result = Kosherz.kosherz_calendar_HebrewDate_new(year, month, day, err)
      Kosherz._wv_check_calendar_error!(err)
      _wv_init(Kosherz._wv_nonnull(result))
    end

    # The Hebrew date of a Gregorian date.
    #
    # # Errors
    #
    # `CalendarError::InvalidDate` when `date` does not exist, or falls outside Hebrew years 1
    # to 9999.
    # @return [HebrewDate]
    def self.from_gregorian(date)
      date_s = Kosherz._wv_encode { |w| Kosherz._wv_write_gregorian_date(w, date) }
      err = ErrorStruct.new
      result = Kosherz.kosherz_calendar_HebrewDate_from_gregorian(date_s, date_s.bytesize, err)
      Kosherz._wv_check_calendar_error!(err)
      _from_ptr(Kosherz._wv_nonnull(result))
    end

    # The year, for example 5785.
    # @return [Integer]
    def year
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        result = Kosherz.kosherz_calendar_HebrewDate_year(_wv_self, err)
        Kosherz._wv_check!(err)
        result
      end
    end

    # The month.
    # @return [Integer]
    def month
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        result = Kosherz.kosherz_calendar_HebrewDate_month(_wv_self, err)
        Kosherz._wv_check!(err)
        result
      end
    end

    # The day of the month, from 1.
    # @return [Integer]
    def day
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        result = Kosherz.kosherz_calendar_HebrewDate_day(_wv_self, err)
        Kosherz._wv_check!(err)
        result
      end
    end

    # The day of the year, from 1 on 1 Tishrei.
    # @return [Integer]
    def day_of_year
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        result = Kosherz.kosherz_calendar_HebrewDate_day_of_year(_wv_self, err)
        Kosherz._wv_check!(err)
        result
      end
    end

    # The day of the week.
    # @return [Integer]
    def weekday
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        result = Kosherz.kosherz_calendar_HebrewDate_weekday(_wv_self, err)
        Kosherz._wv_check!(err)
        result
      end
    end

    # The Gregorian date, if it is in the Gregorian calendar's supported range.
    # @return [GregorianDate, nil]
    def to_gregorian
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        out_len = FFI::MemoryPointer.new(:size_t)
        result = Kosherz.kosherz_calendar_HebrewDate_to_gregorian(_wv_self, out_len, err)
        Kosherz._wv_check!(err)
        Kosherz._wv_decode(result, out_len.read(:size_t)) { |r| Kosherz._wv_read_opt_gregorian_date(r) }
      end
    end

    # The date `days` later, or earlier when negative.
    #
    # # Errors
    #
    # `CalendarError::InvalidDate` outside Hebrew years 1 to 9999.
    # @return [HebrewDate]
    def add_days(days)
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        result = Kosherz.kosherz_calendar_HebrewDate_add_days(_wv_self, days, err)
        Kosherz._wv_check_calendar_error!(err)
        HebrewDate._from_ptr(Kosherz._wv_nonnull(result))
      end
    end

    # The holidays, fasts and other marked days on this day.
    # @return [Array<Holiday>]
    def holidays(region)
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        out_len = FFI::MemoryPointer.new(:size_t)
