  # === Module: calendar.limudim ===

  # Base error for the `calendar.limudim` module's error domain.
  class LimudimError < Error
    # A psalm outside 1 to 150, a verse outside 1 to 176, or a chapter of Pirkei Avos outside 1
    # to 6.
    class InvalidUnit < LimudimError
      CODE = 1

      def initialize(message = nil)
        super(CODE, message || 'A psalm outside 1 to 150, a verse outside 1 to 176, or a chapter of Pirkei Avos outside 1')
      end
    end
  end

  # @api private
  # The LimudimError for a domain `code`, with its payload fields decoded;
  # the root Error (or Cancelled) for any other code.
  def self._wv_limudim_error_from(code, message, payload = nil)
    message = nil if message.empty?
    r = WvBufferReader.new(payload)
    error =
      case code
      when 1
        LimudimError::InvalidUnit.new(message)
      else
        return _wv_error(code, message.to_s)
      end
    r.expect_end!
    error
  end

  # @api private
  # Raises the LimudimError for a non-zero error slot.
  def self._wv_check_limudim_error!(err)
    taken = _wv_take_error(err)
    raise _wv_limudim_error_from(*taken) unless taken.nil?
  end

