  # A side of a page: *amud aleph* (a) or *amud beis* (b).
  module Side
    # The front of the page, "a".
    ALEPH = 0
    # The back of the page, "b".
    BET = 1
  end

  # A day's portion of Tehillim.
  class TehillimUnit
    # The active variant's integer tag.
    def tag
      self.class::TAG
    end

    # Whole chapters, `start` to `end` inclusive.
    class Psalms < TehillimUnit
      TAG = 0

      # The first chapter.
      attr_reader :start

      # The last chapter.
      attr_reader :end_

      def initialize(start:, end_:)
        @start = start
        @end_ = end_
      end

      # Structural equality over every field.
      def ==(other)
        other.is_a?(Psalms) &&
          start == other.start &&
          end_ == other.end_
      end
    end

    # Part of one long chapter (119, split over two days).
    class PsalmVerses < TehillimUnit
      TAG = 1

      # The chapter.
      attr_reader :psalm

      # The first verse.
      attr_reader :start_verse

      # The last verse.
      attr_reader :end_verse

      def initialize(psalm:, start_verse:, end_verse:)
        @psalm = psalm
        @start_verse = start_verse
        @end_verse = end_verse
      end

      # Structural equality over every field.
      def ==(other)
        other.is_a?(PsalmVerses) &&
          psalm == other.psalm &&
          start_verse == other.start_verse &&
          end_verse == other.end_verse
      end
    end
  end

  # The Pirkei Avos read on a Shabbos afternoon.
  class PirkeiAvosUnit
    # The active variant's integer tag.
    def tag
      self.class::TAG
    end

    # One chapter.
    class Single < PirkeiAvosUnit
      TAG = 0

      # The chapter, 1 to 6.
      attr_reader :chapter

      def initialize(chapter:)
        @chapter = chapter
      end

      # Structural equality over every field.
      def ==(other)
        other.is_a?(Single) &&
          chapter == other.chapter
      end
    end

    # Two chapters read together, at the end of the summer.
    class Combined < PirkeiAvosUnit
      TAG = 1

      # The first chapter.
      attr_reader :first

      # The second chapter.
      attr_reader :second

      def initialize(first:, second:)
        @first = first
        @second = second
      end

      # Structural equality over every field.
      def ==(other)
        other.is_a?(Combined) &&
          first == other.first &&
          second == other.second
      end
    end
  end

  # A page (*daf*) of the Talmud: both sides of one leaf.
  class Daf
    # The tractate.
    attr_reader :tractate

    # The page number. The Bavli starts at 2, the Yerushalmi at 1.
    attr_reader :daf

    # As text, for example "Bava Metzia 55".
    attr_reader :display

    def initialize(tractate:, daf:, display:)
      @tractate = tractate
      @daf = daf
      @display = display
    end

    # Structural equality over every field.
    def ==(other)
      other.is_a?(Daf) &&
        tractate == other.tractate &&
        daf == other.daf &&
        display == other.display
    end
  end

  # One side of a page (*amud*).
  class Amud
    # The tractate.
    attr_reader :tractate

    # The page number.
    attr_reader :daf

    # Which side of the page.
    attr_reader :side

    # As text, for example "Bava Metzia 55b".
    attr_reader :display

    def initialize(tractate:, daf:, side:, display:)
      @tractate = tractate
      @daf = daf
      @side = side
      @display = display
    end

    # Structural equality over every field.
    def ==(other)
      other.is_a?(Amud) &&
        tractate == other.tractate &&
        daf == other.daf &&
        side == other.side &&
        display == other.display
    end
  end

  # One *mishnah*.
  class Mishna
    # The tractate.
    attr_reader :tractate

    # The chapter (*perek*), from 1.
    attr_reader :chapter

    # The *mishnah* within the chapter, from 1.
    attr_reader :mishna

    # As text, for example "Nazir 5:5".
    attr_reader :display

    def initialize(tractate:, chapter:, mishna:, display:)
      @tractate = tractate
      @chapter = chapter
