    # Structural equality over every field.
    def ==(other)
      other.is_a?(MishnaPair) &&
        first == other.first &&
        second == other.second &&
        display == other.display
    end
  end

  # @api private
  # Packs a Daf into the value-buffer wire format.
  def self._wv_write_daf(w, v)
