  end

  # @api private
  # Packs a TehillimUnit into the value-buffer wire format.
  def self._wv_write_tehillim_unit(w, v)
    case v
    when TehillimUnit::Psalms
      w.write_i32(0)
      w.write_i32(v.start)
      w.write_i32(v.end_)
    when TehillimUnit::PsalmVerses
      w.write_i32(1)
      w.write_i32(v.psalm)
      w.write_i32(v.start_verse)
      w.write_i32(v.end_verse)
    else
      raise TypeError, "expected a TehillimUnit, got #{v.class}"
    end
  end

  # @api private
  # Unpacks a TehillimUnit from the value-buffer wire format.
  def self._wv_read_tehillim_unit(r)
    tag = r.read_i32
    case tag
    when 0
      TehillimUnit::Psalms.new(start: r.read_i32, end_: r.read_i32)
    when 1
      TehillimUnit::PsalmVerses.new(
        psalm: r.read_i32,
        start_verse: r.read_i32,
        end_verse: r.read_i32,
      )
    else
      raise _wv_malformed("unknown TehillimUnit tag #{tag}")
    end
  end

  # @api private
  # Packs a PirkeiAvosUnit into the value-buffer wire format.
  def self._wv_write_pirkei_avos_unit(w, v)
    case v
    when PirkeiAvosUnit::Single
      w.write_i32(0)
      w.write_i32(v.chapter)
    when PirkeiAvosUnit::Combined
      w.write_i32(1)
      w.write_i32(v.first)
      w.write_i32(v.second)
    else
      raise TypeError, "expected a PirkeiAvosUnit, got #{v.class}"
    end
  end

  # @api private
  # Unpacks a PirkeiAvosUnit from the value-buffer wire format.
  def self._wv_read_pirkei_avos_unit(r)
    tag = r.read_i32
    case tag
    when 0
      PirkeiAvosUnit::Single.new(chapter: r.read_i32)
    when 1
      PirkeiAvosUnit::Combined.new(first: r.read_i32, second: r.read_i32)
    else
      raise _wv_malformed("unknown PirkeiAvosUnit tag #{tag}")
    end
  end

