  # === Module: zmanim ===

  # Base error for the `zmanim` module's error domain.
  class ZmanimError < Error
    # The latitude is not between -90 and 90 degrees.
    class InvalidLatitude < ZmanimError
      CODE = 1

      def initialize(message = nil)
        super(CODE, message || 'The latitude is not between -90 and 90 degrees.')
      end
    end

    # The longitude is not between -180 and 180 degrees.
    class InvalidLongitude < ZmanimError
      CODE = 2

      def initialize(message = nil)
        super(CODE, message || 'The longitude is not between -180 and 180 degrees.')
      end
    end

    # An elevation is negative or not a finite number.
    class InvalidElevation < ZmanimError
      CODE = 3

      def initialize(message = nil)
        super(CODE, message || 'An elevation is negative or not a finite number.')
      end
    end

    # The Gregorian date does not exist, or is outside the supported range.
    class InvalidGregorianDate < ZmanimError
      CODE = 4

      def initialize(message = nil)
        super(CODE, message || 'The Gregorian date does not exist, or is outside the supported range.')
      end
    end

    # A time zone is needed and none was given. The four Kiddush Levana times need one.
    # `Zmanim` and `MyZmanim` also need one at a location more than 150 degrees from
    # Greenwich.
    class TimeZoneRequired < ZmanimError
      CODE = 5

      def initialize(message = nil)
        super(CODE, message || 'A time zone is needed and none was given. The four Kiddush Levana times need one.')
      end
    end

    # The time zone callback failed, or gave an offset of a day or more.
    class TimeZoneCallbackFailed < ZmanimError
      CODE = 6

      def initialize(message = nil)
        super(CODE, message || 'The time zone callback failed, or gave an offset of a day or more.')
      end
    end

    # A number of minutes, for candle lighting or Tzais Ateret Torah, is not a finite number
    # within a day (1440 minutes) either way.
    class InvalidMinutes < ZmanimError
      CODE = 7

      def initialize(message = nil)
        super(CODE, message || 'A number of minutes, for candle lighting or Tzais Ateret Torah, is not a finite number')
      end
    end

    # An angle in degrees is not a finite number.
    class InvalidDegrees < ZmanimError
      CODE = 8

      def initialize(message = nil)
        super(CODE, message || 'An angle in degrees is not a finite number.')
      end
    end

    # The sun stays above the angle the time needs all day, as in the far north in summer.
    class AllDay < ZmanimError
      CODE = 10

      def initialize(message = nil)
        super(CODE, message || 'The sun stays above the angle the time needs all day, as in the far north in summer.')
      end
    end

    # The sun stays below the angle the time needs all day, as in the far north in winter.
    class AllNight < ZmanimError
      CODE = 11

      def initialize(message = nil)
        super(CODE, message || 'The sun stays below the angle the time needs all day, as in the far north in winter.')
      end
    end

    # The time only exists on certain dates, and this is not one.
    class NotApplicable < ZmanimError
      CODE = 12

      def initialize(message = nil)
        super(CODE, message || 'The time only exists on certain dates, and this is not one.')
      end
    end

    # A calculation failed in a way that should not happen; please report the location and
    # date.
    class Unexpected < ZmanimError
      CODE = 13

      def initialize(message = nil)
        super(CODE, message || 'A calculation failed in a way that should not happen; please report the location and')
      end
    end
  end

  # @api private
  # The ZmanimError for a domain `code`, with its payload fields decoded;
  # the root Error (or Cancelled) for any other code.
  def self._wv_zmanim_error_from(code, message, payload = nil)
    message = nil if message.empty?
    r = WvBufferReader.new(payload)
    error =
      case code
      when 1
        ZmanimError::InvalidLatitude.new(message)
      when 2
        ZmanimError::InvalidLongitude.new(message)
      when 3
        ZmanimError::InvalidElevation.new(message)
      when 4
        ZmanimError::InvalidGregorianDate.new(message)
      when 5
        ZmanimError::TimeZoneRequired.new(message)
      when 6
        ZmanimError::TimeZoneCallbackFailed.new(message)
      when 7
        ZmanimError::InvalidMinutes.new(message)
      when 8
        ZmanimError::InvalidDegrees.new(message)
      when 10
        ZmanimError::AllDay.new(message)
      when 11
        ZmanimError::AllNight.new(message)
      when 12
        ZmanimError::NotApplicable.new(message)
      when 13
        ZmanimError::Unexpected.new(message)
      else
        return _wv_error(code, message.to_s)
      end
    r.expect_end!
    error
  end

  # @api private
  # Raises the ZmanimError for a non-zero error slot.
  def self._wv_check_zmanim_error!(err)
    taken = _wv_take_error(err)
    raise _wv_zmanim_error_from(*taken) unless taken.nil?
  end

