  # What kind of time a `Zman` is.
  module Category
    # Start and end of astronomical, civil and nautical twilight.
    TWILIGHT = 0
    # Dawn (*alos*).
    ALOS = 1
    # Earliest time for tallis and tefillin (*misheyakir*).
    MISHEYAKIR = 2
    # Sunrise (*netz*).
    NETZ = 3
    # Latest time for the morning Shema.
    SOF_ZMAN_SHMA = 4
    # Latest time for the morning prayer.
    SOF_ZMAN_TEFILA = 5
    # Latest time to eat chametz on Erev Pesach.
    SOF_ZMAN_ACHILAS_CHAMETZ = 6
    # Latest time to burn chametz on Erev Pesach.
    SOF_ZMAN_BIUR_CHAMETZ = 7
    # Midday (*chatzos hayom*).
    CHATZOS_HAYOM = 8
    # Earliest Mincha (*mincha gedola*).
    MINCHA_GEDOLA = 9
    # *Plag hamincha*.
    PLAG_HAMINCHA = 10
    # Shortly before *mincha ketana*.
    SAMUCH_LE_MINCHA_KETANA = 11
    # Preferred Mincha time (*mincha ketana*).
    MINCHA_KETANA = 12
    # Twilight between sunset and nightfall (*bein hashmashos*).
    BEIN_HASHMASHOS = 13
    # Candle lighting before Shabbos or Yom Tov.
    CANDLE_LIGHTING = 14
    # Sunset (*shkiya*).
    SHKIYA = 15
    # Nightfall (*tzais*).
    TZAIS = 16
    # The window for Kiddush Levana.
    KIDUSH_LEVANA = 17
    # Midnight (*chatzos halayla*).
    CHATZOS_HALAYLA = 18
  end

  # The solar position algorithm.
  module Calculator
    # The NOAA algorithm, KosherJava's default. Good to about a minute.
    NOAA = 0
    # Jean Meeus's higher-accuracy VSOP87 algorithm.
    MEEUS = 1
    # The NREL Solar Position Algorithm, solved on the topocentric zenith.
    SPA = 2
  end

  # Why a time in `ZmanTime` could not be calculated.
  module ZmanFailure
    # The sun stays above the angle the time needs all day.
    ALL_DAY = 0
    # The sun stays below the angle the time needs all day.
    ALL_NIGHT = 1
    # The time does not apply on this date.
    NOT_APPLICABLE = 2
    # The time needs a time zone and none was given. Only the four Kiddush Levana times need
    # one.
    TIME_ZONE_REQUIRED = 3
    # The time zone callback failed.
    TIME_ZONE_CALLBACK_FAILED = 4
    # An internal calculation error.
    UNEXPECTED = 5
  end

  # A place on earth: where to calculate *zmanim* for. Heights are in meters above sea level;
  # leave them 0 for sea level.
  #
  # The time zone is not part of the location. You pass a `TimeZoneOffset` to `Zmanim` and
  # `MyZmanim` when you create them.
  class Location
    # Latitude in degrees, north positive.
    attr_reader :latitude

    # Longitude in degrees, east positive.
    attr_reader :longitude

    # The observer's height. Elevation makes sunrise earlier and sunset later.
    attr_reader :elevation

    # The height of the eastern horizon, over which the sun rises.
    attr_reader :eastern_horizon_elevation

    # The height of the western horizon, behind which the sun sets.
    attr_reader :western_horizon_elevation

    def initialize(
      latitude:,
      longitude:,
      elevation:,
      eastern_horizon_elevation:,
      western_horizon_elevation:
    )
      @latitude = latitude
      @longitude = longitude
      @elevation = elevation
      @eastern_horizon_elevation = eastern_horizon_elevation
      @western_horizon_elevation = western_horizon_elevation
    end

    # Structural equality over every field.
    def ==(other)
      other.is_a?(Location) &&
        latitude == other.latitude &&
        longitude == other.longitude &&
        elevation == other.elevation &&
        eastern_horizon_elevation == other.eastern_horizon_elevation &&
        western_horizon_elevation == other.western_horizon_elevation
    end
  end

  # How `Zmanim` calculates. `default_config` matches KosherJava's defaults.
  class Config
    # How long before sea-level sunset candle lighting is, in minutes, at most 1440 either
    # way. Default 18.
    attr_reader :candle_lighting_minutes

    # Whether proportional zmanim divide the day at astronomical *chatzos*. Default false.
    attr_reader :use_astronomical_chatzos_for_other_zmanim

    # Whether elevation adjusts every zman built on sunrise and sunset, not only sunrise
    # and sunset themselves. Default false.
    attr_reader :use_elevation

    # How long after sunset Tzais Ateret Torah is, in minutes, at most 1440 either way.
    # Default 40.
    attr_reader :ateret_torah_sunset_minutes

    # Whether *chatzos* is the sun's transit rather than the midpoint of sunrise and
    # sunset. Default true.
    attr_reader :use_astronomical_chatzos

    # The solar position algorithm. Default NOAA.
    attr_reader :calculator

    # For Meeus and SPA: whether to apply the delta-T (TT - UT) correction. Default true.
    attr_reader :apply_delta_t

    def initialize(
      candle_lighting_minutes:,
      use_astronomical_chatzos_for_other_zmanim:,
      use_elevation:,
      ateret_torah_sunset_minutes:,
      use_astronomical_chatzos:,
      calculator:,
      apply_delta_t:
    )
      @candle_lighting_minutes = candle_lighting_minutes
      @use_astronomical_chatzos_for_other_zmanim = use_astronomical_chatzos_for_other_zmanim
      @use_elevation = use_elevation
      @ateret_torah_sunset_minutes = ateret_torah_sunset_minutes
      @use_astronomical_chatzos = use_astronomical_chatzos
      @calculator = calculator
      @apply_delta_t = apply_delta_t
    end

    # Structural equality over every field.
    def ==(other)
      other.is_a?(Config) &&
        candle_lighting_minutes == other.candle_lighting_minutes &&
        use_astronomical_chatzos_for_other_zmanim == other.use_astronomical_chatzos_for_other_zmanim &&
        use_elevation == other.use_elevation &&
        ateret_torah_sunset_minutes == other.ateret_torah_sunset_minutes &&
        use_astronomical_chatzos == other.use_astronomical_chatzos &&
        calculator == other.calculator &&
        apply_delta_t == other.apply_delta_t
    end
  end

  # One zman's time, or why it has none.
  class ZmanTime
    # The zman.
    attr_reader :zman

    # The time in Unix milliseconds, when it could be calculated.
    attr_reader :time

    # Why it could not, when it could not.
    attr_reader :failure

    def initialize(zman:, time:, failure:)
      @zman = zman
      @time = time
      @failure = failure
    end

    # Structural equality over every field.
    def ==(other)
      other.is_a?(ZmanTime) &&
        zman == other.zman &&
        time == other.time &&
        failure == other.failure
    end
  end

  # @api private
  # Packs a Location into the value-buffer wire format.
  def self._wv_write_location(w, v)
    w.write_f64(v.latitude)
    w.write_f64(v.longitude)
    w.write_f64(v.elevation)
    w.write_f64(v.eastern_horizon_elevation)
    w.write_f64(v.western_horizon_elevation)
  end

  # @api private
  # Unpacks a Location from the value-buffer wire format.
  def self._wv_read_location(r)
    Location.new(
      latitude: r.read_f64,
      longitude: r.read_f64,
      elevation: r.read_f64,
      eastern_horizon_elevation: r.read_f64,
      western_horizon_elevation: r.read_f64,
    )
  end

  # @api private
  # Packs a Config into the value-buffer wire format.
  def self._wv_write_config(w, v)
    w.write_i32(v.candle_lighting_minutes)
    w.write_bool(v.use_astronomical_chatzos_for_other_zmanim)
    w.write_bool(v.use_elevation)
    w.write_i32(v.ateret_torah_sunset_minutes)
    w.write_bool(v.use_astronomical_chatzos)
    w.write_i32(v.calculator)
    w.write_bool(v.apply_delta_t)
  end

  # @api private
  # Unpacks a Config from the value-buffer wire format.
  def self._wv_read_config(r)
    Config.new(
      candle_lighting_minutes: r.read_i32,
      use_astronomical_chatzos_for_other_zmanim: r.read_bool,
      use_elevation: r.read_bool,
      ateret_torah_sunset_minutes: r.read_i32,
      use_astronomical_chatzos: r.read_bool,
      calculator: r.read_i32,
      apply_delta_t: r.read_bool,
    )
  end

  # @api private
  # Packs a ZmanTime into the value-buffer wire format.
  def self._wv_write_zman_time(w, v)
    w.write_i32(v.zman)
    _wv_write_opt_i64(w, v.time)
    _wv_write_opt_zman_failure(w, v.failure)
  end

  # @api private
  # Unpacks a ZmanTime from the value-buffer wire format.
  def self._wv_read_zman_time(r)
    ZmanTime.new(zman: r.read_i32, time: _wv_read_opt_i64(r), failure: _wv_read_opt_zman_failure(r))
  end

