        Kosherz._wv_check!(err)
        Kosherz._wv_decode(result, out_len.read(:size_t)) { |r| Kosherz._wv_read_list_zman_time(r) }
      end
    end

    # When the sun is `degrees` below the geometric horizon before sunrise, in Unix
    # milliseconds.
