  # MyZmanim's *zmanim* for one place on one day. The location's elevation and horizons
  # matter: MyZmanim gives both "level" and "elevated" sunrise and sunset.
  class MyZmanim < WvObject
    WV_PTR = MyZmanimPtr

    # @api private
    def self._wv_clone(ptr)
      Kosherz.kosherz_zmanim_myzmanim_MyZmanim_clone(ptr)
    end

    # The *zmanim* at `location` on `date` in `time_zone`. Candles are lit
    # `candle_lighting_minutes` before sunset. The website uses 18 minutes by default.
    #
    # The time zone is optional. With a time zone every time works. A location more than
    # 150 degrees from Greenwich needs a time zone. Without one this returns
    # `ZmanimError::TimeZoneRequired`.
    #
    # # Errors
    #
    # - `ZmanimError::InvalidGregorianDate` when the date does not exist.
    # - `ZmanimError::InvalidMinutes` when `candle_lighting_minutes` is not a number or
    #   is more than 1440 minutes either way.
    # - The errors of `validate_location`. This includes `ZmanimError::TimeZoneRequired`
    #   when there is no time zone and the location is more than 150 degrees from
    #   Greenwich.
    def initialize(location, date, candle_lighting_minutes, time_zone = nil)
      location_s = Kosherz._wv_encode { |w| Kosherz._wv_write_location(w, location) }
      date_s = Kosherz._wv_encode { |w| Kosherz._wv_write_gregorian_date(w, date) }
      err = ErrorStruct.new
      time_zone_ctx, time_zone_vtable = Kosherz._wv_cb_register(time_zone, WV_TIME_ZONE_OFFSET_VTABLE)
      result = Kosherz.kosherz_zmanim_myzmanim_MyZmanim_new(location_s, location_s.bytesize, date_s, date_s.bytesize, candle_lighting_minutes, time_zone_ctx, time_zone_vtable, err)
      Kosherz._wv_check_zmanim_error!(err)
      _wv_init(Kosherz._wv_nonnull(result))
    end

    # The time of `zman`, in Unix milliseconds.
    #
    # # Errors
    #
    # `ZmanimError::AllDay` or `ZmanimError::AllNight` where the website shows no
    # time; `ZmanimError::TimeZoneCallbackFailed` when the callback failed.
    # @return [Integer]
    def get(zman)
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        result = Kosherz.kosherz_zmanim_myzmanim_MyZmanim_get(_wv_self, zman, err)
        Kosherz._wv_check_zmanim_error!(err)
        result
      end
    end

    # Every row, with its time or why it has none.
    # @return [Array<MyZmanTime>]
    def all
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        out_len = FFI::MemoryPointer.new(:size_t)
        result = Kosherz.kosherz_zmanim_myzmanim_MyZmanim_all(_wv_self, out_len, err)
        Kosherz._wv_check!(err)
        Kosherz._wv_decode(result, out_len.read(:size_t)) { |r| Kosherz._wv_read_list_my_zman_time(r) }
      end
    end

    # A twelfth of the day from sea-level sunrise to sea-level sunset, in milliseconds.
    #
    # # Errors
    #
    # The same as `get`.
    # @return [Integer]
    def proportional_hour_gra
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        result = Kosherz.kosherz_zmanim_myzmanim_MyZmanim_proportional_hour_gra(_wv_self, err)
        Kosherz._wv_check_zmanim_error!(err)
        result
      end
    end

    # The location.
    # @return [Location]
    def location
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        out_len = FFI::MemoryPointer.new(:size_t)
        result = Kosherz.kosherz_zmanim_myzmanim_MyZmanim_location(_wv_self, out_len, err)
        Kosherz._wv_check!(err)
        Kosherz._wv_decode(result, out_len.read(:size_t)) { |r| Kosherz._wv_read_location(r) }
      end
    end

    # The date.
    # @return [GregorianDate]
    def date
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        out_len = FFI::MemoryPointer.new(:size_t)
        result = Kosherz.kosherz_zmanim_myzmanim_MyZmanim_date(_wv_self, out_len, err)
        Kosherz._wv_check!(err)
        Kosherz._wv_decode(result, out_len.read(:size_t)) { |r| Kosherz._wv_read_gregorian_date(r) }
      end
    end

    # The minutes before sunset of candle lighting.
    # @return [Float]
    def candle_lighting_minutes
      Kosherz._wv_pin(self) do |_wv_self|
        err = ErrorStruct.new
        result = Kosherz.kosherz_zmanim_myzmanim_MyZmanim_candle_lighting_minutes(_wv_self, err)
        Kosherz._wv_check!(err)
        result
      end
    end
